import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print(-1)
        return

    n = int(data[0])

    if n == 0:
        print(-1)
        return

    if len(data) < n + 1:
        print(-1)
        return

    try:
        arr = list(map(int, data[1:n+1]))
    except:
        print(-1)
        return

    if len(arr) != n:
        print(-1)
        return

    arr_sorted = sorted(arr)

    result = []
    for i in range(n - 1):
        result.append(abs(arr_sorted[i] - arr_sorted[i + 1]))

    if not result:
        print(-1)
        return

    max_diff = max(result)
    print(max_diff)

if __name__ == "__main__":
    main()
